use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,process::{Command,Stdio}};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn state()->Value{let mut m=serde_json::Map::new();for p in["/proc/loadavg","/proc/swaps","/sys/fs/cgroup/cpu.max","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/memory.max","/sys/fs/cgroup/memory.events","/sys/fs/cgroup/memory.swap.max","/sys/fs/cgroup/memory.swap.events"]{m.insert(p.into(),fs::read_to_string(p).unwrap().into());}Value::Object(m)}
fn main(){let mode=std::env::args().nth(1).unwrap();assert!(mode=="check"||mode=="run");let manifest=read("/cr/profile-manifest.json");for(p,h)in manifest["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"{p}");}let plan=read("/cr/profile-plan.json");assert_eq!(plan["steps"].as_array().unwrap().len(),16);assert_eq!(manifest["SDK_calls_including_primes"],916);let perf="/usr/lib/linux-tools/6.8.0-147-generic/perf";assert!(Command::new(perf).arg("--version").status().unwrap().success());if mode=="check"{println!("PASS pinned targetprofile paths/plan/perf executable; noSDKcalls or PMU capture");return;}
let latency=read("/output/measure/complete.json");assert_eq!(latency["status"],"complete");assert_eq!(latency["distinct_gnark_exports"],120);let before=state();let quota=before["/sys/fs/cgroup/cpu.max"].as_str().unwrap().split_whitespace().collect::<Vec<_>>();assert_eq!(quota[0].parse::<u64>().unwrap(),96*quota[1].parse::<u64>().unwrap());assert_eq!(before["/sys/fs/cgroup/memory.max"].as_str().unwrap().trim(),(30u64<<30).to_string());assert_eq!(before["/sys/fs/cgroup/memory.swap.max"].as_str().unwrap().trim(),"0");
let r=Path::new("/output/profile");assert!(!r.exists());fs::create_dir(r).unwrap();for d in["perf","stat","proofs"]{fs::create_dir(r.join(d)).unwrap();}for fifo in["ctl","ack"]{assert!(Command::new("mkfifo").arg(r.join(fifo)).status().unwrap().success());}
fs::write(r.join("before.json"),serde_json::to_vec_pretty(&before).unwrap()).unwrap();fs::copy("/cr/profile-plan.json",r.join("diagnostic-plan.json")).unwrap();fs::copy("/cr/profile-pins.json",r.join("diagnostic-pins.json")).unwrap();fs::write(r.join("diagnostic-case.json"),serde_json::to_vec_pretty(&manifest["case"]).unwrap()).unwrap();
let log=fs::File::create(r.join("workflow.log")).unwrap();let status=Command::new("/usr/local/bin/cr-xtask").args(["workflow","/cr/profile-plan.json","/output/profile/diagnostic-run"]).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().unwrap();assert!(status.success(),"preserve profile failure without replay");fs::write(r.join("after.json"),serde_json::to_vec_pretty(&state()).unwrap()).unwrap();println!("COMPLETE fourprofileSDKprocesses/4Gnark; decode quality requires hostreader");}
